def transform(grid):
    # Extract the sequence of colors from non-zero rows in order of appearance
    pattern = []
    for r in range(len(grid)):
        row = grid[r]
        if any(c != 0 for c in row):
            # Find the first non-zero value in the row
            for val in row:
                if val != 0:
                    pattern.append(val)
                    break

    if not pattern:
        return grid

    period = len(pattern)
    height = len(grid)
    width = len(grid[0])

    result = []
    for r in range(height):
        pattern_idx = r % period
        row_color = pattern[pattern_idx]
        result.append([row_color] * width)

    return result
